response:
I assumed r03 works the same way as this script. The config prompts and tool schemas come in through args, and the subject agent lists the tool calls it would make instead of running them.

**Gates before launch.** I run six gates before I launch. First, `git status` must be clean, and `git log -1 -- spe/predictions/r04.yaml spe/plans/r04.md` must show the commit from 10 minutes ago. That proves the prediction was locked before any data existed. Second, I diff this script against spe/evals/harness/r03-workflow.js. The only changes should be the two configs, the Opus judge, the trial loop, and the cap. Third, I smoke-test spe/evals/graders/grade.py in two ways. Grading answers.json against itself must score 100%. Grading a copy with every category changed must score 0% on category. Fourth, I check that the ticket file and spe/evals/tasks/answers.json hold the same 50 ticket IDs. Fifth, I price the run from round 3's recorded per-call spend. The run makes 500 subject calls and 500 Opus judge calls, and that total must come in under $40. The script refuses to start if it does not. These prices are estimates. Sixth, I do a dry run with `limit: 2, trials: 1`, which makes 8 agent calls. I check that the records come back in the shape grade.py reads. Then I commit the script locally as spe/evals/harness/r04-workflow.js and launch it. I do not push, and the commit has no Claude attribution. answers.json never goes into args, so no agent in the run can see the answer key. grade.py scores the returned records after the run ends.

```js
export const meta = {
  name: "spe-r04-eval",
  description: "SPE round 4. Configs B (12-line prompt, 6 tools) and C2 (12-line prompt, 3 tools plus check_status) on 50 tickets, 5 trials per cell. An Opus judge scores reply tone with spe/evals/graders/judge.md. spe/evals/graders/grade.py scores labels after the run. Estimated spend is capped at $40.",
  phases: ["Validate", "Trials", "Report"],
}

// args shape:
// {
//   tickets: [{ id, subject, body, customer }],            // 50 tickets
//   configs: { B: { systemPrompt, tools: [{ name, description, input_schema }] },
//              C2: { systemPrompt, tools: [...] } },
//   judgeRubric: "<contents of spe/evals/graders/judge.md>",
//   subjectModel: "<same subject model as r03>",
//   estCostUsd: { run: <per subject call>, judge: <per Opus judge call> },
//   labelSet: { categories: [...], priorities: [...] },    // optional, allowed values only
//   trials: 5, capUsd: 40, limit: <dry run only>
// }

const CONFIG_IDS = ["B", "C2"]
const EXPECTED_TICKETS = 50
const DEFAULT_TRIALS = 5
const HARD_CAP_USD = 40

// ---------- Validate ----------
phase("Validate")

const a = args || {}
const problems = []

const limit = Number.isInteger(a.limit) && a.limit > 0 ? a.limit : null
const allTickets = Array.isArray(a.tickets) ? a.tickets : []
if (!Array.isArray(a.tickets)) problems.push("args.tickets must be an array")
const tickets = limit ? allTickets.slice(0, limit) : allTickets
if (!limit && tickets.length !== EXPECTED_TICKETS) {
  problems.push(`expected ${EXPECTED_TICKETS} tickets, got ${tickets.length}`)
}
if (new Set(tickets.map(t => t.id)).size !== tickets.length) problems.push("ticket ids are not unique")

for (const c of CONFIG_IDS) {
  const cfg = a.configs && a.configs[c]
  if (!cfg || typeof cfg.systemPrompt !== "string" || !Array.isArray(cfg.tools)) {
    problems.push(`args.configs.${c} needs systemPrompt and tools`)
    continue
  }
  const lines = cfg.systemPrompt.trim().split("\n").length
  if (lines !== 12) problems.push(`config ${c} prompt should be 12 lines, has ${lines}`)
}
const toolNames = c => ((a.configs && a.configs[c] && a.configs[c].tools) || []).map(t => t.name)
if (a.configs && a.configs.B && toolNames("B").length !== 6) {
  problems.push(`config B should have 6 tools, has ${toolNames("B").length}`)
}
if (a.configs && a.configs.C2) {
  const n = toolNames("C2")
  if (n.length !== 4 || !n.includes("check_status")) problems.push("config C2 should have 3 tools plus check_status")
}

if (typeof a.judgeRubric !== "string" || !a.judgeRubric.trim()) {
  problems.push("args.judgeRubric must hold the text of spe/evals/graders/judge.md")
}
if (typeof a.subjectModel !== "string" || !a.subjectModel) {
  problems.push("args.subjectModel is required. Use the r03 subject model")
}
if (!a.estCostUsd || !(a.estCostUsd.run > 0) || !(a.estCostUsd.judge > 0)) {
  problems.push("args.estCostUsd.run and args.estCostUsd.judge are required")
}
if (a.answers) problems.push("do not pass answers.json into the workflow. grade.py reads it after the run")

const trials = Number.isInteger(a.trials) && a.trials > 0 ? a.trials : DEFAULT_TRIALS
const capUsd = typeof a.capUsd === "number" ? Math.min(a.capUsd, HARD_CAP_USD) : HARD_CAP_USD

if (problems.length) throw new Error("r04 args invalid:\n- " + problems.join("\n- "))

const cellsPerTrial = tickets.length * CONFIG_IDS.length
const perTrialCost = cellsPerTrial * (a.estCostUsd.run + a.estCostUsd.judge)
const projected = perTrialCost * trials
log(`Plan: ${tickets.length} tickets x ${CONFIG_IDS.length} configs x ${trials} trials = ${cellsPerTrial * trials} subject runs and ${cellsPerTrial * trials} judge calls.`)
log(`Estimated spend is $${projected.toFixed(2)}. The cap is $${capUsd}.`)
if (projected > capUsd) {
  throw new Error(`Estimated spend $${projected.toFixed(2)} is over the $${capUsd} cap. Revise spe/plans/r04.md before running.`)
}

// ---------- Schemas ----------
const strOrEnum = vals => (Array.isArray(vals) && vals.length ? { type: "string", enum: vals } : { type: "string" })

const runSchema = {
  type: "object",
  required: ["ticket_id", "tool_calls", "label", "reply"],
  properties: {
    ticket_id: { type: "string" },
    tool_calls: {
      type: "array",
      items: {
        type: "object",
        required: ["tool", "input"],
        properties: { tool: { type: "string" }, input: { type: "object" } },
      },
    },
    label: {
      type: "object",
      required: ["category", "priority"],
      properties: {
        category: strOrEnum(a.labelSet && a.labelSet.categories),
        priority: strOrEnum(a.labelSet && a.labelSet.priorities),
      },
    },
    reply: { type: "string" },
  },
}

const judgeSchema = {
  type: "object",
  required: ["tone_score", "pass", "rationale"],
  properties: {
    tone_score: { type: "integer", minimum: 1, maximum: 5 },
    pass: { type: "boolean" },
    rationale: { type: "string", maxLength: 400 },
  },
}

// ---------- Prompts ----------
function subjectPrompt(cfg, ticket) {
  return [
    cfg.systemPrompt.trim(),
    "",
    "## Tools available to you",
    "You cannot execute these tools in this run. List every call you would make, in order, in tool_calls. Use only these tool names.",
    JSON.stringify(cfg.tools, null, 2),
    "",
    "## Ticket",
    `ID: ${ticket.id}`,
    `Subject: ${ticket.subject || ""}`,
    `From: ${ticket.customer || "unknown"}`,
    "",
    String(ticket.body || ""),
    "",
    "## Output",
    "Do not read files, search, or run commands. Work only from this message.",
    "Return ticket_id, tool_calls, label.category, label.priority, and the reply you would send the customer.",
  ].join("\n")
}

// The judge sees the ticket and the reply only. It never sees the config, the label, or the tool calls.
function judgePrompt(ticket, reply) {
  return [
    a.judgeRubric.trim(),
    "",
    "## Ticket",
    `Subject: ${ticket.subject || ""}`,
    "",
    String(ticket.body || ""),
    "",
    "## Reply to score",
    reply,
    "",
    "Score only the tone of the reply, using the rubric above. Do not read files or run commands.",
  ].join("\n")
}

// ---------- Spend tracking (estimates) ----------
let spent = 0

async function call(kind, prompt, opts) {
  const cost = a.estCostUsd[kind]
  for (let attempt = 1; attempt <= 2; attempt++) {
    if (spent + cost > capUsd) throw new Error("spend cap reached")
    spent += cost
    try {
      return await agent(prompt, opts)
    } catch (e) {
      if (attempt === 2) throw e
      log(`Retrying ${opts.label}: ${String(e).slice(0, 200)}`)
    }
  }
}

// ---------- One cell: subject run, then blind judge ----------
async function runCell({ ticket, config, trial }) {
  const cfg = a.configs[config]
  const rec = {
    ticket_id: ticket.id, config, trial,
    label: null, tool_calls: [], unknown_tools: [], reply: null,
    judge: null, run_error: null, judge_error: null,
  }
  try {
    const out = await call("run", subjectPrompt(cfg, ticket), {
      label: `r04 ${config} t${trial} ${ticket.id}`,
      phase: "Trials",
      schema: runSchema,
      model: a.subjectModel,
    })
    rec.label = out.label
    rec.tool_calls = out.tool_calls
    rec.reply = out.reply
    const allowed = new Set(cfg.tools.map(t => t.name))
    rec.unknown_tools = out.tool_calls.map(t => t.tool).filter(n => !allowed.has(n))
    if (out.ticket_id !== ticket.id) rec.run_error = `ticket_id mismatch: got ${out.ticket_id}`
  } catch (e) {
    rec.run_error = String(e).slice(0, 300)
    return rec
  }
  try {
    rec.judge = await call("judge", judgePrompt(ticket, rec.reply), {
      label: `r04 judge t${trial} ${ticket.id}`,
      phase: "Trials",
      schema: judgeSchema,
      model: "opus",
    })
  } catch (e) {
    rec.judge_error = String(e).slice(0, 300)
  }
  return rec
}

// ---------- Trials ----------
// Each trial covers every ticket for both configs. A cap stop happens only between trials, so every cell has the same number of trials.
phase("Trials")

const records = []
let completedTrials = 0
for (let t = 1; t <= trials; t++) {
  if (spent + perTrialCost > capUsd) {
    log(`Stopping before trial ${t}. Estimated spend is $${spent.toFixed(2)}, and a full trial would pass the $${capUsd} cap.`)
    break
  }
  const cells = []
  for (const ticket of tickets) {
    for (const config of CONFIG_IDS) cells.push({ ticket, config, trial: t })
  }
  const results = await parallel(cells.map(cell => () => runCell(cell)))
  records.push(...results)
  completedTrials = t
  const runErrs = results.filter(r => r.run_error).length
  const judgeErrs = results.filter(r => r.judge_error).length
  log(`Trial ${t} done. ${results.length} cells, ${runErrs} run errors, ${judgeErrs} judge errors. Estimated spend is $${spent.toFixed(2)}.`)
}

// ---------- Report ----------
phase("Report")

const mean = xs => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null)
const rate = (xs, f) => (xs.length ? xs.filter(f).length / xs.length : null)

function summarize(config) {
  const rs = records.filter(r => r.config === config)
  const ok = rs.filter(r => !r.run_error)
  const judged = ok.filter(r => r.judge)
  return {
    cells: rs.length,
    run_errors: rs.length - ok.length,
    judge_errors: ok.length - judged.length,
    mean_tool_calls: mean(ok.map(r => r.tool_calls.length)),
    unknown_tool_rate: rate(ok, r => r.unknown_tools.length > 0),
    check_status_rate: rate(ok, r => r.tool_calls.some(x => x.tool === "check_status")),
    mean_tone_score: mean(judged.map(r => r.judge.tone_score)),
    tone_pass_rate: rate(judged, r => r.judge.pass),
  }
}

const summary = { B: summarize("B"), C2: summarize("C2") }
log(`B: ${JSON.stringify(summary.B)}`)
log(`C2: ${JSON.stringify(summary.C2)}`)
log("Label accuracy is not computed here. Run spe/evals/graders/grade.py on the returned records.")

return {
  round: "r04",
  plan: "spe/plans/r04.md",
  predictions: "spe/predictions/r04.yaml",
  dry_run: Boolean(limit),
  trials_planned: trials,
  trials_completed: completedTrials,
  est_spend_usd: Number(spent.toFixed(2)),
  cap_usd: capUsd,
  summary,
  records,
}
